"""Distinct Minchah readings, read from printed 157–188 (IA n181–n212)."""
NACHEM_HE = ('נַחֵם, יְיָ אֱלֹהֵֽינוּ, אֶת אֲבֵלֵי צִיּוֹן וְאֶת אֲבֵלֵי יְרוּשָׁלָֽיִם, וְאֶת הָעִיר הָאֲבֵלָה וְהַחֲרֵבָה, וְהַבְּזוּיָה וְהַשּׁוֹמֵמָה: הָאֲבֵלָה מִבְּלִי בָנֶֽיהָ, וְהַחֲרֵבָה מִמְּעוֹנוֹתֶֽיהָ, וְהַבְּזוּיָה מִכְּבוֹדָהּ, וְהַשּׁוֹמֵמָה מֵאֵין יוֹשֵׁב. וְהִיא יוֹשֶֽׁבֶת וְרֹאשָׁהּ חָפוּי, כְּאִשָּׁה עֲקָרָה שֶׁלֹּא יָלָֽדָה; וַיְבַלְּעֽוּהָ לִיגְיוֹנוֹת, וַיִּירָשֽׁוּהָ עוֹבְדֵי פְסִילִים, וַיָּטִֽילוּ אֶת עַמְּךָ יִשְׂרָאֵל לֶחָֽרֶב, וַיַּהַרְגוּ בְזָדוֹן חֲסִידֵי עֶלְיוֹן. עַל כֵּן צִיּוֹן בְּמַר תִּבְכֶּה, וִירוּשָׁלַֽיִם תִּתֵּן קוֹלָהּ. לִבִּי לִבִּי עַל חַלְלֵיהֶם, מֵעַי מֵעַי עַל חַלְלֵיהֶם. כִּי אַתָּה, יְיָ, בָּאֵשׁ הִצַּתָּהּ, וּבָאֵשׁ אַתָּה עָתִיד לִבְנוֹתָהּ, כָּאָמוּר: ')
NACHEM_VERSE_HE = 'וַאֲנִי אֶהְיֶה לָּהּ, נְאֻם יְיָ, חוֹמַת אֵשׁ סָבִיב, וּלְכָבוֹד אֶהְיֶה בְתוֹכָהּ.'
NACHEM_SEAL_HE = 'בָּרוּךְ אַתָּה, יְיָ, מְנַחֵם צִיּוֹן וּבוֹנֵה יְרוּשָׁלָֽיִם.'
NACHEM_EN = ('Comfort, Lord our God, the mourners of Zion, the mourners of Jerusalem, and the city that is in mourning, laid waste, despised and desolate. She is in mourning because she is without her children; she is laid waste as to her homes; she is despised in the downfall of her glory; she is desolate through the loss of her inhabitants. She sits with her head covered like a barren, childless woman. Legions devoured her; idolators took possession of her; they put thy people Israel to the sword, and killed wantonly the faithful followers of the Most High. Because of that, Zion weeps bitterly; Jerusalem raises her voice. How my heart grieves for the slain! How my heart yearns for the slain! Thou, O Lord, didst consume her with fire, and with fire thou wilt in future rebuild her, as it is said: ')
NACHEM_VERSE_EN = '“I will be to her,” says the Lord, “a wall of fire round about; and for glory I will be in the midst of her.”'
NACHEM_SEAL_EN = 'Blessed art thou, O Lord, Comforter of Zion and Builder of Jerusalem.'
SHALOM_RAV = {
    'he': 'שָׁלוֹם רָב עַל יִשְׂרָאֵל עַמְּךָ תָּשִׂים לְעוֹלָם, כִּי אַתָּה הוּא מֶֽלֶךְ אָדוֹן לְכָל הַשָּׁלוֹם, וְטוֹב בְּעֵינֶֽיךָ לְבָרֵךְ אֶת עַמְּךָ יִשְׂרָאֵל בְּכָל עֵת וּבְכָל שָׁעָה בִּשְׁלוֹמֶֽךָ.',
    'en': 'O grant abundant peace to Israel thy people forever, for thou art the King and Lord of all peace. May it please thee to bless thy people Israel with peace at all times and at all hours.'}
TACHANUN_RUBRIC = ('Taḥanun is recited on weekday afternoons, except on Fridays and the following occasions: Erev Rosh Ḥodesh and Rosh Ḥodesh, the entire month of Nisan, the day preceding Lag b’Omer and Lag b’Omer, the first eight days of Sivan, the 8th, 9th, 14th and 15th of Av, from Erev Yom Kippur until the second day after Sukkoth, from the 24th of Kislev until after Ḥanukkah, the 14th and 15th of Shevat, the 13th, 14th and 15th of Adar and Adar Sheni. Taḥanun is also omitted in the house of a mourner during the week of mourning, and on the occasion of a Brith Milah.')
TORAH_RUBRIC = ('On fast days (except Tish‘ah b’Av) the Torah is taken out before the Shemoneh Esreh is recited, and Exodus 32:11–14 and 34:1–10 is read (if ten people fasting are present). The Torah reading is followed by the Haftarah taken from Isaiah 55:6–56:8.')
